UPDATE TBL_MIS_LEAD
   SET PAT_NM = #{patNm}, BIRTH6 = #{birth6}, GENDER = #{gender}, GUARD_NM = #{guardNm}, GUARD_REL = #{guardRel}, TEL = #{tel}
     , CONTACT_DT = #{contactDt}, CHANNEL = #{channel}, COND_MEMO = #{condMemo}, STAGE = #{stage}, PLAN_DT = #{planDt}
     , NEXT_DT = #{nextDt}, NEXT_MEMO = #{nextMemo}, ADMIT_DT = #{admitDt}, DISCH_DT = #{dischDt}, CLOSE_RSN = #{closeRsn}, UPD_USER = #{userId}
 WHERE HOSP_CD = #{hospCd} AND LEAD_SEQ = #{leadSeq}

UPDATE TBL_MIS_NOTI_USER
   SET NAME = #{name}, ROLE_NM = #{roleNm}, EMAIL = #{email}, TEL = #{tel}, MAIL_YN = #{mailYn}, SMS_YN = #{smsYn}
     , AUTO_GB = #{autoGb}, MIN_LEVEL = #{minLevel}, USE_YN = #{useYn}, UPD_USER = #{userId}
 WHERE HOSP_CD = #{hospCd} AND NOTI_SEQ = #{notiSeq}

