SELECT DATA_GB AS datagb, MAP_JSON AS mapjson, HDR_ROW AS hdrrow, DATE_FORMAT(UPD_DTTM,'%Y-%m-%d %H:%i') AS upddttm, UPD_USER AS upduser
  FROM TBL_MIS_EMR_MAP
 WHERE HOSP_CD = #{hospCd}
